  var cross='';for(i=0;i<7;i++){cross+='M'+(208+i*5.4)+' 128L'+(206+i*6)+' 168';cross+='M'+(206+i*6)+' 128L'+(212+i*5)+' 168';}
  var nail=function(x,y){return '<circle cx="'+x+'" cy="'+y+'" r="1.4" fill="url(#san'+k+')" stroke="#6a4a10" stroke-width=".4"/>';};
